const OWNER_OF={bat:'Battery systems specialist',bms:'Battery systems specialist',pump:'Thermal systems specialist',cont:'High-voltage safety specialist',har:'High-voltage safety specialist',port:'Charging systems specialist',obc:'Charging systems specialist',mot:'Drive unit specialist',inv:'Drive unit specialist',dcdc:'Electrical and network specialist',lv:'Electrical and network specialist',tcu:'Electrical and network specialist',info:'Electrical and network specialist',hvac:'Climate systems specialist',brk:'Chassis specialist',sus:'Chassis specialist'};


/* ---- 05-fleet.js ---- */
/* ===== The fleet: 12,000 sampled vehicles standing for about 1.15 million connected EVs across six segments.
   Each sampled vehicle carries a weight (v.w) = vehicles it stands for; every count shown on screen is a weighted count. ===== */
const PLANTCODE={Hosur:'H',Pune:'P',Chennai:'C',Dharwad:'D'},YEARCODE={2023:'P',2024:'R',2025:'S',2026:'T'};
const FLEET=[];
function swFor(m,buildM,saleDay){
 // Returns [software version, days ago it was installed]
 if(m.id==='ZS1'){if(buildM>=34)return['3.2.1',saleDay];const base=buildM<12?'3.0.4':buildM<24?'3.1.2':'3.2.0';if(buildM>=28)return rnd()<.3?['3.2.1',Math.min(saleDay,rint(8,40))]:['3.2.0',saleDay];
  if(rnd()<.62)return rnd()<.3?['3.2.1',Math.min(saleDay,rint(8,40))]:['3.2.0',Math.min(saleDay,rint(140,215))];return[base==='3.2.0'?'3.1.2':base,saleDay];}
 if(m.id==='KS4'){if(buildM>=33)return['1.0.5',saleDay];return rnd()<.25?['1.0.5',Math.min(saleDay,rint(10,45))]:['1.0.3',saleDay];}
 const fam={'2W':['2.0.3','2.1.0','2.2.4'],'3W':['4.1.0','4.2.2','4.3.0'],'CAR':['2.3.6','2.4.1','2.5.0'],'LCV':['5.0.2','5.1.1','5.2.0'],'BUS':['7.2.0','7.3.1','7.4.0'],'TRK':['6.0.4','6.1.0','6.2.2']}[m.seg];
 let i=buildM<12?0:buildM<24?1:2;if(i<2&&rnd()<.45)i++;return[fam[i],saleDay];}
(function buildFleet(){
 const stW=STATES.map(s=>[s[0],s[4]]);let serial=100000;
 for(const S of SEGS){const ms=MODELS.filter(m=>m.seg===S.id),w=S.fleet/S.sample;
  for(let n=0;n<S.sample;n++){
   const m=MODEL[wpick(ms.map(x=>[x.id,x.share]))];
   const months=[];for(let b=m.launch;b<=35;b++)months.push([b,Math.min(1.5,.35+(b-m.launch)/(m.id==='KS4'?3:14))]);
   const buildM=wpick(months),buildDay=Math.max(1,(35-buildM)*MONTH_DAYS+rnd()*MONTH_DAYS-20);
   const lag=(S.id==='BUS'||S.id==='TRK'?22:12)+rnd()*46,saleDay=buildDay-lag,inService=saleDay>1;
   const st=wpick(stW),SS=STATE[st],city=pick(SS.cities);
   const usage=wpick(USAGE[S.id]),daily=Math.max(6,(S.daily[0]+gauss()*S.daily[1]*.45)*Math.pow(USEMULT[usage],.85));
   const ageD=inService?saleDay:0,odo=Math.round(ageD*daily*(.85+.3*rnd()));
   const dc=clamp(S.id==='BUS'?.72+gauss()*.1:S.id==='2W'?.04+rnd()*.08:['Personal'].includes(usage)?.14+gauss()*.09:.44+gauss()*.2,0,.95);
   const line=wpick(m.lines),shift=wpick(SHIFTS),lots={},yr=yearOfM(buildM);
   for(const c of COMPS)lots[c.id]=c.sup[rnd()<.55?0:1]+'-'+yymm(buildM);
   const [sw,swDay]=swFor(m,buildM,Math.max(saleDay,0));
   let tcu='1.7.9',tcuDay=Math.max(saleDay,0);if(['KC3','KX5','LV1'].includes(m.id)&&buildM<=31){const u=rnd();if(u<.36){tcu='1.8.2';tcuDay=Math.min(tcuDay,rint(120,230));}else if(u<.44){tcu='1.8.4';tcuDay=Math.min(tcuDay,rint(10,60));}}else if(buildM>31)tcu='1.8.4';
   const i=FLEET.length;serial+=rint(1,9);
   FLEET.push({i,vin:'MR9'+(m.id+'XX').slice(0,4)+'E'+YEARCODE[yr]+PLANTCODE[m.plant]+String(serial).padStart(7,'0'),seg:S.id,model:m.id,w,buildM,buildDay,buildY:String(yr),saleDay,inService,
    stock:inService?'With customer':buildDay<9?'Plant yard':buildDay<22?'In transit':'Dealer stock',st,state:SS.name,city,zone:SS.zone,amb:SS.amb+gauss()*1.2,usage,daily:r0(daily),odo,dc:r2(dc),payload:r2(rnd()),
    plant:m.plant,line,shift,lots,sw,swDay,tcu,tcuDay,chem:m.chem,dealer:S.id==='BUS'?city+' depot':city+' '+['North','Central','South'][rint(0,2)],
    iss:[],claims:[],dtcs:[],fails:[],pred:[],pAny:[0,0,0]});
  }}
})();
const INSVC=FLEET.filter(v=>v.inService);
const VIN_IDX=new Map(FLEET.map(v=>[v.vin,v]));
const WSUM=a=>{let t=0;for(const v of a)t+=v.w;return t;};
const misOf=v=>v.saleDay/MONTH_DAYS;
const inWarranty=(v,dayAgo,comp)=>{const ageM=(v.saleDay-dayAgo)/MONTH_DAYS,odo=v.odo*(v.saleDay?((v.saleDay-dayAgo)/v.saleDay):0);if(comp==='bat'||comp==='bms')return ageM<=96&&odo<=SEG[v.seg].kmLimit*1.6;return ageM<=36&&odo<=SEG[v.seg].kmLimit;};
const vfind=q=>{q=String(q||'').toUpperCase().trim();if(!q)return null;return VIN_IDX.get(q)||(q.length>=5?FLEET.find(v=>v.vin.includes(q)):null)||null;};

/* Shared cohort filter used by every screen. */
function csel(p,base){p=p||{};let a=base||FLEET;
 if(p.seg)a=a.filter(v=>v.seg===p.seg);if(p.model)a=a.filter(v=>v.model===p.model);if(p.zone)a=a.filter(v=>v.zone===p.zone);if(p.state)a=a.filter(v=>v.st===p.state);
 if(p.plant)a=a.filter(v=>v.plant===p.plant);if(p.line)a=a.filter(v=>v.line===p.line);if(p.shift)a=a.filter(v=>v.shift===p.shift);if(p.usage)a=a.filter(v=>v.usage===p.usage);if(p.sw)a=a.filter(v=>v.sw===p.sw);if(p.tcu)a=a.filter(v=>v.tcu===p.tcu);
 if(p.buildY)a=a.filter(v=>v.buildY===p.buildY);if(p.buildFrom!==undefined&&p.buildFrom!=='')a=a.filter(v=>v.buildM>=+p.buildFrom);if(p.buildTo!==undefined&&p.buildTo!=='')a=a.filter(v=>v.buildM<=+p.buildTo);
 if(p.lot){const [c,l]=String(p.lot).split(':');a=a.filter(v=>v.lots[c]===l);}
 if(p.supplier&&p.comp)a=a.filter(v=>v.lots[p.comp].startsWith(p.supplier+'-'));
 if(p.issue&&ISSUE[p.issue])a=a.filter(v=>v.iss.some(x=>x.id===p.issue));
 return a;}
const cohortText=p=>{const t=[];p=p||{};if(p.seg)t.push(SEG[p.seg].name);if(p.model)t.push(MODEL[p.model].name);if(p.zone)t.push(p.zone);if(p.state)t.push(STATE[p.state].name);if(p.plant)t.push(p.plant+(p.line?' '+p.line:''));if(p.usage)t.push(p.usage);if(p.sw)t.push('software '+p.sw);if(p.buildY)t.push('built '+p.buildY);if(p.issue)t.push('issue '+p.issue);return t.length?t.join(', '):'All vehicles';};

/* KPI model. A vehicle's value for a KPI = typical value + stable vehicle noise + a small model offset + the effect of any issue it carries.
   Nothing is stored: the value is recomputed from hashes, so it is identical on every request. */
const KPIS=[];
SIGKPI.forEach(k=>KPIS.push({key:k[1],cat:k[0],name:k[2],desc:k[3],unit:k[4],lo:k[5],hi:k[6],base:k[7],sd:(k[6]-k[5])*.06,comp:null,dir:null,src:'trip'}));
SIGCATS.push('Component health indicators');
HEALTH.forEach(h=>KPIS.push({key:h[0],cat:14,name:h[1],desc:h[2],unit:h[3],lo:h[4],hi:h[5],base:h[6],sd:(h[5]-h[4])*h[9],comp:h[7],dir:h[8],src:'health'}));
KPIS.forEach((k,j)=>{k.j=j;k.dp=k.sd<.05?3:k.sd<.5?2:k.sd<5?1:0;});
const KPI_IDX=Object.fromEntries(KPIS.map(k=>[k.key,k]));
ISSUES.forEach(I=>{I.sigMap=Object.fromEntries(I.sig);I.h=hstr(I.id);});
const MODEL_H=Object.fromEntries(MODELS.map(m=>[m.id,hstr(m.id)]));
// z = how many standard deviations the vehicle sits from the typical value. trip: undefined for the vehicle aggregate, else trip number 0..n-1 (latest last).
function kz(v,K,trip,nTrips){const j=K.j;let z=.8*hn(v.i,j*7+1)+.7*(h32(MODEL_H[v.model],j)-.5);
 if(K.cat===10&&v.zone===ZONES[0])z+=.6;
 for(const a of v.iss){if(a.p<=0)continue;const I=ISSUE[a.id],p=trip===undefined?a.p:a.p*(.45+.55*trip/Math.max(1,nTrips-1));
  if(K.src==='health'){const s=I.sigMap[K.key];if(s)z+=s*p;}
  else if(I.cats.includes(K.cat)&&h32(I.h,j)<.3)z+=(h32(I.h,j+99)<.5?-1.7:1.7)*p;}
 if(trip!==undefined)z+=.9*hn(v.i*131+trip*17+3,j*3+5);
 return z;}
const kv=(v,K,trip,nTrips)=>{const x=clamp(K.base+kz(v,K,trip,nTrips)*K.sd,K.lo,K.hi);return+x.toFixed(K.dp);};
const kvKey=(v,key)=>kv(v,KPI_IDX[key]);


/* ---- 06-events.js ---- */
/* ===== Events: failures, warranty claims and fault-code events, generated from the component life models and the planted issues. ===== */
const DTC=Object.fromEntries(DTCS.map(d=>[d[0],{code:d[0],def:d[1],comp:d[2],sys:d[3],part:d[4],mode:d[5],crit:d[6],safety:d[7],does:d[8],notices:d[9],causes:d[10],fix:d[11],parts:d[12],check:d[13]}]));
const CRIT=['','Critical','High','Medium','Low'];
const CLAIMS=[],DTCE=[],DTC_WINDOW=400;
const SYMPTOM={bat:['Reduced range and power warning','Battery warning lamp, charging refused','Vehicle stopped with battery over-temperature message'],bms:['Range drops suddenly at low charge','Battery warning, power cut at low charge','State of charge jumps'],mot:['Jerking under acceleration','Loss of drive with EV system warning','Whine from drive unit'],inv:['Reduced power on climbs','EV system warning, vehicle will not go READY','Repeated power limit message'],
 obc:['AC charging stops after a few minutes','Vehicle will not charge at home','Charger fault message'],dcdc:['12 V warning lamp while driving','Multiple warning lamps, low system voltage'],port:['Charging stops, connector hot to touch','Connector will not lock','Charging interrupted repeatedly'],pump:['Reduced power in hot weather','Battery temperature warning','Coolant pump noisy'],cont:['Vehicle will not go READY','EV system warning after switch-off','Charging will not start'],
 lv:['Vehicle will not start after parking','12 V battery flat','Vehicle dead after a weekend'],tcu:['Connected services offline','12 V battery flat after parking','App shows vehicle unreachable'],brk:['Brake pedal feel changed','Brake warning lamp','Regeneration weak'],sus:['Knocking from rear over bumps','Steering feels loose','Uneven tyre wear'],hvac:['Cabin not cooling','A/C cuts out in traffic','A/C slow to cool'],info:['Screen restarts while driving','Blank screen, no reverse camera','Cluster freezes'],har:['Intermittent EV system warning','Isolation warning in rain']};
const TECHNOTE={ok:['Part replaced, fault cleared, road test passed.','Replaced as per diagnostic tree. Vehicle returned to customer.','Fault confirmed and part replaced.'],nff:['Part replaced as precaution. Could not reproduce the fault in the workshop.','Replaced the part. Customer returned later with the same complaint.','No stored fault at the time of visit; part replaced on symptom.'],repeat:['Repeat visit for the same complaint. Replaced again.','Second repair for this symptom. Escalated to technical support.']};
let claimSeq=260000;
function mkClaim(v,trueComp,I,failDay,repeatOf){
 const claimComp=I&&I.claimAs?wpick(I.claimAs):trueComp,C=COMP[claimComp],S=SEG[v.seg];
 const nff=I?(claimComp!==trueComp||rnd()<I.nff):rnd()<.05;
 const lag=rint(1,12),day=failDay-lag;
 // A repair in the last few days has not reached the warranty system yet: claims lag the failure, which is why claims alone detect late.
 if(day<0)return{nff:false,id:null,unfiled:true};
 const partF=claimComp==='bat'?(rnd()<.7?.32:1):1;
 const parts=r0(C.part*S.cost*partF*(.82+.4*rnd())),labour=r0(C.lab*LABOUR_RATE*Math.pow(S.cost,.5)*(.8+.5*rnd())),other=C.stop?r0((1800+rnd()*2400)*Math.pow(S.cost,.6)):0;
 const supResp=I?(I.causeType==='Supplier part'||I.causeType==='Design margin'):rnd()<.22;
 const recoverable=supResp&&!nff?r0(parts*.75):0;
 const recState=!recoverable?'Not recoverable':I&&(I.status==='Root cause confirmed'||I.status==='Countermeasure in field')?(rnd()<.62?'Recovered':'Claimed, awaiting supplier'):I?'Not yet claimed':rnd()<.5?'Recovered':'Claimed, awaiting supplier';
 const mis=Math.max(0,(v.saleDay-failDay)/MONTH_DAYS);
 const c={id:'WC'+(++claimSeq),v:v.i,comp:claimComp,trueComp,issue:I?I.id:null,failDay,day,mis:r1(mis),odo:r0(v.odo*(v.saleDay?clamp((v.saleDay-failDay)/v.saleDay,0,1):0)),nff,repeatOf:repeatOf||null,parts,labour,other,total:parts+labour+other,
  status:day<25&&rnd()<.5?'Pending':rnd()<.045?'Rejected':'Approved',dealer:v.dealer,recoverable,recState,recovered:recState==='Recovered'?recoverable:0,
  symptom:pick(SYMPTOM[trueComp==='tcu'&&claimComp==='lv'?'lv':claimComp]),note:pick(repeatOf?TECHNOTE.repeat:nff?TECHNOTE.nff:TECHNOTE.ok)};
 CLAIMS.push(c);v.claims.push(c);return c;}
(function simulate(){
 for(const v of INSVC){const mis=misOf(v);
  for(const C of COMPS){if(C.exclude.includes(v.seg))continue;
   let best={t:weibT(C.base[0],C.base[1]/Math.pow(USEMULT[v.usage],.3)),I:null,a:null};
   for(const I of ISSUES){if(I.comp!==C.id||!I.pred(v))continue;
    const z=gauss(),acc=I.accel(v)*Math.exp(.4*z),expDay=I.id==='Q-102'||I.id==='Q-109'?Math.min(v.saleDay,v.swDay):I.id==='Q-106'?Math.min(v.saleDay,v.tcuDay):v.saleDay;
    const T=weibT(I.k,I.eta/acc),expM=expDay/MONTH_DAYS;
    const a={id:I.id,z,acc,T,expM,x:(T-expM)*MONTH_DAYS,fixed:false,p:0,failed:false};v.iss.push(a);
    const tSale=(v.saleDay-expDay)/MONTH_DAYS+T;if(tSale<best.t)best={t:tSale,I,a};}
   if(best.t>mis)continue;
   const failDay=v.saleDay-best.t*MONTH_DAYS,I=best.I,a=best.a;
   v.fails.push({comp:C.id,day:failDay,issue:I?I.id:null});
   // A base failure replaces the part, which also removes any issue carried by that part.
   v.iss.forEach(x=>{if(ISSUE[x.id].comp===C.id&&x!==a&&ISSUE[x.id].causeType!=='Software'){x.fixed=true;}});
   if(a)a.failed=true;
   if(!inWarranty(v,failDay,C.id)){if(a)a.fixed=true;continue;}
   let c=mkClaim(v,C.id,I,failDay,null),d=failDay,guard=0;
   // No-fault-found repairs do not fix the vehicle: the fault returns until the true cause is repaired.
   while(c.nff&&guard++<3){const again=I?rnd()<.68:rnd()<.25;if(!again){if(a)a.fixed=true;break;}
    d=d-rint(18,85);if(d<=0){if(a){a.x=-d+rint(3,25);a.fixed=false;a.pending=true;}break;}
    c=mkClaim(v,C.id,I,d,c.id);if(!c.nff&&a)a.fixed=true;}
   if(a&&!c.nff)a.fixed=true;
  }
  // Precursor strength now: 0 = nothing visible, 1 = at the point of failure.
  for(const a of v.iss){const I=ISSUE[a.id];if(a.fixed){a.p=0;continue;}if(a.failed&&!a.pending){a.p=0;a.fixed=true;continue;}
   const x=Math.max(0,a.x);a.p=r2(clamp(Math.pow(clamp(1-x/I.sigLead,0,1),.7)+.1*Math.max(0,a.z),0,1.25));}
 }
 // Fault-code events inside the last 400 days.
 const bg=DTCS.map(d=>[d[0],d[6]>=3?5:d[6]===2?1.1:.05]);
 const ev=(v,code,day,cnt,fixedAfter)=>{if(day<0||day>DTC_WINDOW||day>v.saleDay)return;const D=DTC[code];if(COMP[D.comp].exclude.includes(v.seg))return;
  const e={v:v.i,code,day:r1(day),n:cnt,odo:r0(v.odo*(1-day/Math.max(1,v.saleDay))),phase:D.sys==='Charging'?'Charging':wpick([['Driving',.62],['Charging',.2],['Parked',.18]]),soc:rint(8,98),temp:r0(v.amb+gauss()*6),spd:0,
   st:fixedAfter!==null&&day>fixedAfter?'Stored':day<16?'Active':'Stored'};e.spd=e.phase==='Driving'?rint(8,96):0;DTCE.push(e);v.dtcs.push(e);};
 for(const v of INSVC){
  const lam=.75*Math.min(v.saleDay,DTC_WINDOW)/365*Math.pow(USEMULT[v.usage],.4);let n=0,L=Math.exp(-lam),p=1;do{n++;p*=rnd();}while(p>L);n--;
  for(let k=0;k<n;k++)ev(v,wpick(bg),rnd()*Math.min(v.saleDay,DTC_WINDOW),rint(1,3),null);
  for(const a of v.iss){const I=ISSUE[a.id];if(!I.seq.length)continue;
   // Every failure of this issue on this vehicle is preceded by the code sequence; pending repeats are still building up.
   const fd=v.claims.filter(c=>c.issue===I.id).map(c=>c.failDay);if(!a.fixed)fd.push(-Math.max(0,a.x));else if(a.failed&&!fd.length){const f=v.fails.find(f=>f.issue===I.id);if(f)fd.push(f.day);}
   const Lv=I.lead*Math.exp(.35*gauss()),m=I.seq.length;
   for(const F of fd){const repaired=F>=0?F:null;
    I.seq.forEach((code,j)=>{const onset=F+Lv*((m-j)/m);let d=onset;let reps=0;while(d>F&&reps<7){if(d>=0)ev(v,code,d,rint(1,j===m-1?3:9),repaired);d-=rint(3,11)*(1+j*.3);reps++;}
     if(j===m-1&&F>=0)ev(v,code,F+rnd()*.8,rint(1,4),repaired);});}
  }
 }
 CLAIMS.sort((a,b)=>a.day-b.day);DTCE.sort((a,b)=>a.day-b.day);
})();
const claimW=c=>FLEET[c.v].w;
const CLAIM_IDX=new Map(CLAIMS.map(c=>[c.id,c]));


/* ---- 07-predict.js ---- */
/* ===== Predictive failure. For every vehicle and component: the probability of failure within 30, 60 and 90 days and the expected days to failure.
   The estimate uses only what a real model could observe: age, cohort membership, usage, health-indicator drift and fault codes, plus estimation noise.
   It is a demonstration of the output a trained model would give, not a trained model. ===== */
const HZ=[30,60,90];
const medResid=(t,k,eta)=>(eta*Math.pow(Math.pow(t/eta,k)+Math.LN2,1/k)-t)*MONTH_DAYS;
const condP=(t,h,k,eta)=>1-weibS(t+h/MONTH_DAYS,k,eta)/weibS(t,k,eta);
(function predict(){
 for(const v of INSVC){const mis=misOf(v);let surv=[1,1,1];
  for(const C of COMPS){if(C.exclude.includes(v.seg))continue;
   const eta=C.base[1]/Math.pow(USEMULT[v.usage],.3),replaced=v.fails.filter(f=>f.comp===C.id).sort((a,b)=>a.day-b.day)[0],t=replaced?replaced.day/MONTH_DAYS:mis;
   let p=HZ.map(h=>condP(t,h,C.base[0],eta)),ttf=medResid(t,C.base[0],eta),driver='Wear and age',conf='Low',evid=[];
   for(const a of v.iss){const I=ISSUE[a.id];if(I.comp!==C.id||a.fixed)continue;
    const zh=a.z+.5*hn(v.i,a.id.charCodeAt(4)*31+5),acc=I.accel(v)*Math.exp(.4*zh),ei=I.eta/acc;
    let pi=HZ.map(h=>condP(a.expM,h,I.k,ei)),ti=medResid(a.expM,I.k,ei);conf='Medium';
    evid=['In the affected cohort for '+I.id+': '+I.name.toLowerCase()];
    const pv=clamp(a.p-.1*Math.max(0,zh),0,1);
    if(pv>.1){const xh=Math.max(2,I.sigLead*(1-Math.pow(pv,1/.7)))*Math.exp(.35*hn(v.i+17,a.id.charCodeAt(4)*13+1));
     const ps=HZ.map(h=>normCdf((Math.log(h)-Math.log(xh))/.6));pi=pi.map((x,i)=>Math.max(x,ps[i]));ti=Math.min(ti,xh);conf=a.p>.45?'High':'Medium';
     const top=I.sig.map(s=>[s[0],s[1]*a.p]).sort((x,y)=>Math.abs(y[1])-Math.abs(x[1]))[0];evid.push(KPI_IDX[top[0]].name+' is '+r1(Math.abs(top[1]))+' standard deviations '+(top[1]>0?'above':'below')+' peers');}
    const codes=uniq(v.dtcs.filter(e=>I.seq.includes(e.code)&&e.day<90).map(e=>e.code));if(codes.length)evid.push('Fault code'+(codes.length>1?'s ':' ')+codes.join(', ')+' in the last 90 days');
    if(a.pending)evid.push('Earlier repair did not fix the cause; the fault is expected to return');
    if(pi[2]>p[2]){p=pi;ttf=ti;driver=I.id;}}
   // A few healthy vehicles get a false alarm, as any real model would produce.
   if(driver==='Wear and age'&&h32(v.i,C.id.charCodeAt(0)*7+C.id.length)<.0008){const f=.25+.4*h32(v.i,91);p=[f*.4,f*.75,f];ttf=60+120*h32(v.i,92);conf='Low';evid=['Unusual '+KPIS.filter(k=>k.comp===C.id).map(k=>k.name.toLowerCase())[0]+' pattern, no cohort link'];driver='Anomaly';}
   p=p.map(x=>clamp(x,0,.995));
   if(p[2]>=.015)v.pred.push({comp:C.id,p:p.map(x=>r2(x*100)/100),p90:p[2],ttf:r0(Math.max(1,ttf)),driver,conf,evid});
   if(C.stop)surv=surv.map((s,i)=>s*(1-p[i]));
  }
  v.pred.sort((a,b)=>b.p90-a.p90);v.pAny=surv.map(s=>r2(1-s));
 }
})();
