/* ---- What Sage is told, and its keyword fallback when no AI key is set ---- */
function assistantContext(rid){const r=ROLE[rid]||ROLES[0],iss=ISSUES.filter(I=>rid!=='RCL'||(HANDOVER[I.id]||'').startsWith('Approved'));
 return`You are Sage, the assistant inside EV_Analytics_Quality, a quality analytics product for an electric-vehicle maker. All data is synthetic demo data; say so if asked about accuracy. The reader is: ${r.name}. They see: ${r.scope}.${r.notSee.length?' Never reveal: '+r.notSee.join('; ')+'.':''}
Answer in plain, short sentences. Use only the facts below and any screen data supplied. Do not invent numbers. If the answer is not in the data, say so and name the screen that would show it.
FLEET: ${num(WSUM(FLEET))} connected EVs across ${SEGS.map(s=>s.name+' '+num(s.fleet)).join(', ')}.
${rid==='RCL'?'':`WARRANTY last 12 months: ${inr(costW(CLAIMS.filter(c=>c.day<365)))} over ${num(wcl(CLAIMS.filter(c=>c.day<365)))} claims.\nALERTS: ${ALERTS.length} open (${SEV.map(s=>ALERTS.filter(a=>a.severity===s).length+' '+s.toLowerCase()).join(', ')}).\n`}ISSUES:
${iss.map(I=>{const s=ISTAT[I.id];return`${I.id} ${I.name} | ${I.models.map(m=>MODEL[m].name).join(', ')} | ${COMP[I.comp].name} | safety ${I.safety}/3 | ${I.status} | ${num(s.openW)} vehicles at risk | ${num(s.e90)} failures expected in 90 days | ${num(s.n30)} likely within 30 days${rid==='RCL'?'':` | ${num(s.claimsW)} claims, ${inr(s.cost)} | cause: ${I.cause}`} | action: ${I.fix} | recall handover: ${HANDOVER[I.id]||'not proposed'}`;}).join('\n')}
${rid==='RCL'?'':'AGENT FINDINGS:\n'+FINDINGS.slice(0,10).map(f=>`${f.id} ${f.title}. ${f.summary.join(' ')} Proposed: ${f.actions.map(a=>a.text).join('; ')}`).join('\n')}`;}
function assistantLocal(rid,q){const s=String(q||'').toLowerCase(),lim=rid==='RCL',iss=ISSUES.filter(I=>!lim||(HANDOVER[I.id]||'').startsWith('Approved'));
 const vm=String(q||'').toUpperCase().match(/MR9[A-Z0-9]{6,14}/),v=vm&&vfind(vm[0]);
 if(v){const b=v.pred.find(x=>x.driver!=='Wear and age');return`${v.vin} is a ${MODEL[v.model].name} in ${v.city}, built ${mlabel(v.buildM)}, ${num(v.odo)} km. ${lim?'':v.claims.length+' warranty claim(s). '}${b?`Highest risk: ${COMP[b.comp].name.toLowerCase()}, ${r0(b.p[2]*100)}% within 90 days, about ${b.ttf} days.`:'No elevated failure risk.'} Open it in ${lim?'Vehicle 360':'AI root cause'} for the full report.`;}
 const im=iss.find(I=>s.includes(I.id.toLowerCase())||I.name.toLowerCase().split(/[ :,]+/).filter(w=>w.length>4).some(w=>s.includes(w))||s.includes(COMP[I.comp].name.toLowerCase()));
 if(im){const st=ISTAT[im.id];return`${im.id} ${im.name} (${im.status}). ${im.mode} ${lim?'':'Cause: '+im.cause+' '}${num(st.openW)} vehicles are still at risk and ${num(st.e90)} failures are expected within 90 days. Action: ${im.fix}`;}
 if(/first|bring in|priorit|recall|which vehicles/.test(s)){const c=iss.filter(I=>I.safety>=3).sort((a,b)=>ISTAT[b.id].n30-ISTAT[a.id].n30)[0]||iss[0];return c?`Start with ${c.id} ${c.name}: ${num(ISTAT[c.id].n30)} vehicles are more likely than not to fail within 30 days. The ordered list is on the Recall risk list page.`:'No approved list yet.';}
 if(lim)return'I can answer about approved recall lists and individual vehicles. Try an issue number or a VIN.';
 if(/cost|expens|90 days|money/.test(s)){const t=[...iss].sort((a,b)=>ISTAT[b.id].e90*ISTAT[b.id].avgCost-ISTAT[a.id].e90*ISTAT[a.id].avgCost)[0],st=ISTAT[t.id];return`${t.id} ${t.name} carries the largest 90-day exposure: about ${inr(st.e90*st.avgCost)} from ${num(st.e90)} expected failures. Warranty cost in the last 12 months was ${inr(costW(CLAIMS.filter(c=>c.day<365)))}.`;}
 if(/decision|today|urgent|critical|alert/.test(s)){const c=ALERTS.filter(a=>a.severity==='Critical');return`${c.length} critical alerts are open. ${c.slice(0,3).map(a=>a.title+' ('+a.source.toLowerCase()+')').join('. ')}. ${sum(FINDINGS.map(f=>f.actions.length))} agent actions are waiting for approval on the AI agents page.`;}
 if(/supplier|lot|recover/.test(s)){const f=FINDINGS.find(x=>x.agent==='recov');return f?f.title+'. '+f.summary.join(' '):'See Supplier and plant quality.';}
 if(/no.fault|nff|repeat/.test(s)){const c=CLAIMS.filter(c=>c.day<365);return`${pct(c.filter(x=>x.nff).length,c.length)}% of claims in the last 12 months were no-fault-found, costing ${inr(costW(c.filter(x=>x.nff)))}. The largest source is ${ISSUE['Q-106'].name.toLowerCase()}.`;}
 return'No AI key is configured on this deployment, so this is a keyword match. Try an issue number such as Q-106, a component, a VIN, or ask about alerts, cost, suppliers, no-fault-found or which vehicles to bring in first.';}


